+import Link from 'next/link';
+import { ChevronLeft } from 'lucide-react';
+import { getStore } from '@/lib/session-store';
+import { getRoiSummary } from '@/lib/analytics/roi-metrics';
+import { Card } from '@/design-system/primitives';
+
+const PLATFORM_COST_USD = 200;
+
+function fmt(n: number, decimals = 0): string {
+  return n.toLocaleString('en-US', { maximumFractionDigits: decimals });
+}
+
+export default function RoiReportPage() {
+  const db = getStore().getDatabase();
+  const summary = getRoiSummary(db, PLATFORM_COST_USD, 90);
+
+  return (
+    <main className="min-h-screen bg-ds-bg py-4 sm:py-8 px-3 sm:px-4">
+      <div className="max-w-3xl mx-auto space-y-6">
+        <Link
+          href="/dashboard"
+          className="flex items-center gap-1 text-sm text-ds-text-muted hover:text-ds-text transition-colors duration-ds-fast"
+        >
+          <ChevronLeft className="h-4 w-4" /> Back to Dashboard
+        </Link>
+
+        <div>
+          <h1 className="text-xl font-bold text-ds-text">ROI Report</h1>
+          <p className="text-sm text-ds-text-muted">Last 90 days · Platform cost ${fmt(PLATFORM_COST_USD)} / voyage</p>
+        </div>
+
+        {summary.totalVoyages === 0 ? (
+          <Card padding="md">
+            <p className="text-sm text-ds-text-muted text-center py-6">
+              No voyage data yet. ROI metrics are populated as deals are closed.
+            </p>
+          </Card>
+        ) : (
+          <>
+            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
+              <Card padding="md">
+                <p className="text-xs text-ds-text-muted">Voyages</p>
+                <p className="text-2xl font-bold text-ds-text mt-1">{fmt(summary.totalVoyages)}</p>
+              </Card>
+              <Card padding="md">
+                <p className="text-xs text-ds-text-muted">Total Savings</p>
+                <p className="text-2xl font-bold text-ds-text mt-1">${fmt(summary.totalSavingsUsd)}</p>
+              </Card>
+              <Card padding="md">
+                <p className="text-xs text-ds-text-muted">Avg / Voyage</p>
+                <p className="text-2xl font-bold text-ds-text mt-1">${fmt(summary.avgSavingsPerVoyage)}</p>
+              </Card>
+              <Card padding="md">
+                <p className="text-xs text-ds-text-muted">ROI Multiple</p>
+                <p className="text-2xl font-bold text-ds-text mt-1">{fmt(summary.roiMultiple, 1)}×</p>
+              </Card>
+            </div>
+
+            {summary.cohorts.length > 0 && (
+              <Card padding="md">
+                <h2 className="text-sm font-semibold text-ds-text mb-3">Monthly Breakdown</h2>
+                <div className="space-y-2">
+                  {summary.cohorts.map((c) => (
+                    <div key={c.month} className="flex justify-between items-center text-sm py-1 border-b border-ds-border last:border-0">
+                      <span className="text-ds-text-muted">{c.month}</span>
+                      <span className="text-ds-text-muted">{c.voyages} voyages</span>
+                      <span className="font-medium text-ds-text">${fmt(c.totalSavings)}</span>
+                    </div>
+                  ))}
+                </div>
+              </Card>
+            )}
+          </>
+        )}
+      </div>
+    </main>
+  );
+}
