- * @returns Object with rowsChanged and yamlVersion
- */
-export async function refreshJwc(
-  db: Database.Database,
-  yamlPath?: string
-): Promise<{ rowsChanged: number; yamlVersion: string }> {
-  const syncId = reportSyncStarted(db, 'jwc');
-
-  try {
