+++ b/scripts/backfill-lastcargoes.ts
@@ -0,0 +1,79 @@
+/**
+ * Idempotent backfill: apply regex lastCargoes extraction to existing sessions
+ * where the LLM returned null for the field.
+ *
+ * Safe to run multiple times — only updates vessels where lastCargoes is null.
+ *
+ * Usage: npx tsx scripts/backfill-lastcargoes.ts [--dry-run]
+ */
+import Database from 'better-sqlite3';
+import * as path from 'path';
+import { extractLastCargoesFromBody } from '../lib/parsing/lastcargoes-fallback';
+
+const isDry = process.argv.includes('--dry-run');
+const dbPath = process.env.SESSIONS_DB_PATH ?? path.join(process.cwd(), 'data', 'sessions.db');
+const db = new Database(dbPath, { readonly: isDry });
+
+interface Email {
+  id: string;
+  body?: string | null;
+}
+
+interface ParsedVessel {
+  emailId: string;
+  lastCargoes?: string | null;
+  [key: string]: unknown;
+}
+
+interface SessionData {
+  emails?: Email[];
+  parsedVessels?: ParsedVessel[];
+  [key: string]: unknown;
+}
+
+interface SessionRow {
+  id: string;
+  data: string;
+}
+
+const sessions = db.prepare<[], SessionRow>('SELECT id, data FROM sessions').all();
+let totalSessions = 0;
+let totalUpdated = 0;
+
+for (const session of sessions) {
+  let data: SessionData;
+  try {
+    data = JSON.parse(session.data) as SessionData;
+  } catch {
+    continue;
+  }
+
+  const vessels = data.parsedVessels ?? [];
+  const emails = data.emails ?? [];
+  const emailBodyMap = new Map(emails.map(e => [e.id, e.body ?? null]));
+
+  let sessionUpdated = 0;
+  for (const vessel of vessels) {
+    if (vessel.lastCargoes) continue;
+
+    const body = emailBodyMap.get(vessel.emailId);
+    if (!body) continue;
+
+    const extracted = extractLastCargoesFromBody(body);
+    if (!extracted) continue;
+
+    vessel.lastCargoes = extracted;
+    sessionUpdated++;
+  }
+
+  if (sessionUpdated > 0) {
+    totalSessions++;
+    totalUpdated += sessionUpdated;
+    if (!isDry) {
+      db.prepare('UPDATE sessions SET data = ? WHERE id = ?').run(JSON.stringify(data), session.id);
+    }
+    console.log(`[${isDry ? 'DRY' : 'UPD'}] session ${session.id}: ${sessionUpdated} vessel(s) backfilled`);
+  }
+}
+
+console.log(`\nDone. ${totalUpdated} vessel(s) across ${totalSessions} session(s) ${isDry ? 'would be' : 'were'} updated.`);

