-
-type Phase = 'view' | 'executing' | 'done' | 'error';
-
-export function ApprovePlanModal({
-  plan,
-  onReject,
-  onComplete,
-  fetcher,
-}: ApprovePlanModalProps) {
-  const fetchFn = fetcher ?? fetch;
