+import type { VesselPassport } from '@/lib/vessel/passport';
+import { Card } from '@/design-system/primitives';
+
+function Row({ label, value }: { label: string; value: string | number | null | undefined }) {
+  if (value == null || value === '') return null;
+  return (
+    <div className="flex justify-between text-sm py-1 border-b border-ds-border last:border-0">
+      <span className="text-ds-text-muted">{label}</span>
+      <span className="font-medium text-ds-text">{value}</span>
+    </div>
+  );
+}
+
+export function VesselPassportPanel({ passport }: { passport: VesselPassport }) {
+  return (
+    <Card padding="md">
+      <h3 className="text-sm font-semibold text-ds-text mb-3">Vessel Passport</h3>
+
+      <div className="space-y-0">
+        <Row label="IMO" value={passport.imo} />
+        <Row label="Name" value={passport.vesselName} />
+        <Row label="Flag" value={passport.flag} />
+        <Row label="Built" value={passport.built} />
+        <Row label="DWT (summer)" value={passport.dwtSummer != null ? `${passport.dwtSummer.toLocaleString()} MT` : null} />
+        <Row label="Type" value={passport.vesselType} />
+        <Row label="Class Society" value={passport.classSociety} />
+        <Row label="P&I Club" value={passport.pandi} />
+        <Row label="Geared" value={passport.geared == null ? null : passport.geared ? 'Yes' : 'No'} />
+      </div>
+
+      {passport.psc && (
+        <div className="mt-3 pt-3 border-t border-ds-border">
+          <p className="text-xs font-semibold text-ds-text-muted mb-1">PSC History</p>
+          <div className="space-y-0">
+            <Row label="Inspections" value={passport.psc.totalInspections} />
+            <Row label="Detentions" value={passport.psc.totalDetentions} />
+            {passport.psc.lastInspectionDate && (
+              <Row label="Last Inspection" value={passport.psc.lastInspectionDate} />
+            )}
+            {passport.psc.lastAuthority && (
+              <Row label="Authority" value={passport.psc.lastAuthority} />
+            )}
+          </div>
+        </div>
+      )}
+
+      {passport.omissions.length > 0 && (
+        <div className="mt-3 pt-3 border-t border-ds-border">
+          <p className="text-xs text-ds-text-subtle">
+            Not shown: {passport.omissions.join(' · ')}
+          </p>
+        </div>
+      )}
+    </Card>
+  );
+}
