+++ b/lib/vessel/passport.ts
@@ -0,0 +1,87 @@
+/**
+ * Vessel passport — aggregates parsed fields + live PSC history into a
+ * structured summary for display on the vessel detail page.
+ *
+ * Data sources:
+ *   - Parsed vessel fields (flag, class society, P&I, built, DWT, type, IMO)
+ *   - PSC detention history from psc_detention_history table (requires
+ *     PSC_DETENTION_ENABLED=true and an external sync — see psc-adapter.ts)
+ *
+ * Intentionally omitted (no sync source as of wave D):
+ *   - Sanctions / shadow-fleet status (see lib/sanctions/sentinel.ts for
+ *     offline corpus; full live sync not yet wired)
+ *   - IACS class registry cross-check (no API client implemented)
+ *   - IG P&I club membership registry (no API client implemented)
+ */
+
+import type Database from 'better-sqlite3';
+import { cfValue, type ParsedVessel } from '@/lib/types';
+import { getDetentionHistory } from '@/lib/market/psc-repository';
+
+export interface PscSummary {
+  totalInspections: number;
+  totalDetentions: number;
+  lastInspectionDate: string | null;
+  lastAuthority: string | null;
+}
+
+export interface VesselPassport {
+  imo: string | null;
+  vesselName: string | null;
+  flag: string | null;
+  built: number | null;
+  dwtSummer: number | null;
+  vesselType: string | null;
+  classSociety: string | null;
+  pandi: string | null;
+  geared: boolean | null;
+  /** null when PSC_DETENTION_ENABLED=false or IMO unknown */
+  psc: PscSummary | null;
+  /** Fields omitted — document why */
+  omissions: string[];
+}
+
+export function buildVesselPassport(
+  vessel: ParsedVessel,
+  db: Database.Database
+): VesselPassport {
+  const pscEnabled = process.env.PSC_DETENTION_ENABLED === 'true';
+  const imo = vessel.imo ?? null;
+
+  let psc: PscSummary | null = null;
+  if (pscEnabled && imo) {
+    const history = getDetentionHistory(db, imo);
+    psc = {
+      totalInspections: history.length,
+      totalDetentions: history.filter((r) => r.detained).length,
+      lastInspectionDate: history[0]?.inspection_date ?? null,
+      lastAuthority: history[0]?.authority ?? null,
+    };
+  }
+
+  const omissions: string[] = [];
+  if (!pscEnabled || !imo) {
+    omissions.push(
+      pscEnabled
+        ? 'PSC history unavailable: IMO number missing'
+        : 'PSC history disabled (PSC_DETENTION_ENABLED=false)'
+    );
+  }
+  omissions.push('Sanctions / shadow-fleet: no live sync source');
+  omissions.push('IACS class registry cross-check: not implemented');
+  omissions.push('IG P&I club registry: not implemented');
+
+  return {
+    imo,
+    vesselName: cfValue(vessel.vesselName),
+    flag: vessel.flag,
+    built: vessel.built,
+    dwtSummer: vessel.dwtSummer?.value ?? null,
+    vesselType: vessel.vesselType,
+    classSociety: vessel.classSociety,
+    pandi: vessel.pandi,
+    geared: vessel.geared,
+    psc,
+    omissions,
+  };
+}
diff --git a/scripts/backfill-lastcargoes.ts b/scripts/backfill-lastcargoes.ts
new file mode 100644
index 00000000..635717b3
--- /dev/null
+++ b/scripts/backfill-lastcargoes.ts
@@ -0,0 +1,101 @@
+#!/usr/bin/env tsx
+/**
+ * Idempotent backfill: populate lastCargoes from email body regex when LLM missed it.
+ *
+ * Reads parsed_results (parse_type='vessel') from the sessions DB.
+ * For each vessel where lastCargoes is null, fetches the email body from
+ * the emails table and applies extractLastCargoesFromBody.
+ * LLM values always take priority — only null entries are touched.
+ *
+ * Usage:
+ *   SESSIONS_DB_PATH=data/sessions.db npx tsx scripts/backfill-lastcargoes.ts
+ *   SESSIONS_DB_PATH=data/sessions.db npx tsx scripts/backfill-lastcargoes.ts --dry-run
+ */
+
+import Database from 'better-sqlite3';
+import { extractLastCargoesFromBody } from '@/lib/parsing/lastcargoes-fallback';
+
+const DB_PATH = process.env.SESSIONS_DB_PATH;
+if (!DB_PATH) {
+  console.error('SESSIONS_DB_PATH is required');
+  process.exit(1);
+}
+
+const dryRun = process.argv.includes('--dry-run');
+
+interface ParsedRow {
+  rowid: number;
+  account_id: string;
+  gmail_message_id: string;
+  result_json: string;
+}
+
+interface EmailRow {
+  body: string;
+}
+
+function main() {
+  const db = new Database(DB_PATH);
+
+  const rows = db
+    .prepare<[], ParsedRow>(
+      `SELECT rowid, account_id, gmail_message_id, result_json
+       FROM parsed_results
+       WHERE parse_type = 'vessel'`
+    )
+    .all();
+
+  let updated = 0;
+  let skipped = 0;
+
+  for (const row of rows) {
+    let vessels: Record<string, unknown>[];
+    try {
+      vessels = JSON.parse(row.result_json);
+      if (!Array.isArray(vessels)) vessels = [vessels];
+    } catch {
+      skipped++;
+      continue;
+    }
+
+    let changed = false;
+    for (const v of vessels) {
+      if (v.lastCargoes != null) continue;
+
+      const emailRow = db
+        .prepare<[string, string], EmailRow>(
+          `SELECT body FROM emails WHERE account_id = ? AND gmail_message_id = ? LIMIT 1`
+        )
+        .get(row.account_id, row.gmail_message_id);
+
+      if (!emailRow?.body) continue;
+
+      const extracted = extractLastCargoesFromBody(emailRow.body);
+      if (!extracted) continue;
+
+      v.lastCargoes = extracted;
+      changed = true;
+    }
+
+    if (!changed) { skipped++; continue; }
+
+    if (!dryRun) {
+      db.prepare(
+        `UPDATE parsed_results SET result_json = ? WHERE rowid = ?`
+      ).run(JSON.stringify(vessels), row.rowid);
+    }
+
+    updated++;
+    console.log(
+      `${dryRun ? '[DRY RUN] ' : ''}Updated vessel in email ${row.gmail_message_id}`
+    );
+  }
+
+  console.log(
+    `\n${dryRun ? '[DRY RUN] ' : ''}Done: ${updated} updated, ${skipped} skipped (already had lastCargoes or no body)`
+  );
+
+  db.close();
+}
+
+main();
