@@ -0,0 +1,74 @@
+import { getStore } from '@/lib/session-store';
+import { getRoiSummary } from '@/lib/analytics/roi-metrics';
+import { Card } from '@/design-system/primitives';
+import Link from 'next/link';
+import { ChevronLeft } from 'lucide-react';
+
+const PLATFORM_COST_USD_PER_VOYAGE = 250;
+
+function fmt(n: number, decimals = 0): string {
+  return n.toLocaleString('en-US', { maximumFractionDigits: decimals });
+}
+
+export default function RoiReportPage() {
+  const db = getStore().getDatabase();
+  const summary = getRoiSummary(db, PLATFORM_COST_USD_PER_VOYAGE, 90);
+
+  return (
+    <main className="min-h-screen bg-ds-bg py-4 sm:py-8 px-3 sm:px-4">
+      <div className="max-w-3xl mx-auto space-y-6">
+        <Link href="/dashboard" className="flex items-center gap-1 text-sm text-ds-text-muted hover:text-ds-text transition-colors">
+          <ChevronLeft className="h-4 w-4" /> Back to Dashboard
+        </Link>
+
+        <div>
+          <h1 className="text-xl font-bold text-ds-text">ROI Report</h1>
+          <p className="text-sm text-ds-text-muted mt-1">Last 90 days · platform cost ${PLATFORM_COST_USD_PER_VOYAGE}/voyage</p>
+        </div>
+
+        {/* KPI tiles */}
+        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
+          <Card padding="sm" className="text-center">
+            <p className="text-xs text-ds-text-muted uppercase tracking-wide">Voyages</p>
+            <p className="text-2xl font-bold text-ds-text mt-1">{fmt(summary.totalVoyages)}</p>
+          </Card>
+          <Card padding="sm" className="text-center">
+            <p className="text-xs text-ds-text-muted uppercase tracking-wide">Total savings</p>
+            <p className="text-2xl font-bold text-ds-text mt-1">${fmt(summary.totalSavingsUsd)}</p>
+          </Card>
+          <Card padding="sm" className="text-center">
+            <p className="text-xs text-ds-text-muted uppercase tracking-wide">Avg / voyage</p>
+            <p className="text-2xl font-bold text-ds-text mt-1">${fmt(summary.avgSavingsPerVoyage)}</p>
+          </Card>
+          <Card padding="sm" className="text-center">
+            <p className="text-xs text-ds-text-muted uppercase tracking-wide">ROI multiple</p>
+            <p className="text-2xl font-bold text-ds-text mt-1">{summary.roiMultiple > 0 ? `${fmt(summary.roiMultiple, 1)}×` : '—'}</p>
+          </Card>
+        </div>
+
+        {/* Cohort breakdown */}
+        {summary.cohorts.length > 0 ? (
+          <Card padding="md">
+            <h2 className="text-sm font-semibold text-ds-text mb-3">Monthly breakdown</h2>
+            <div className="divide-y divide-ds-border">
+              {summary.cohorts.map(c => (
+                <div key={c.month} className="flex items-center justify-between py-2 text-sm">
+                  <span className="text-ds-text-muted">{c.month}</span>
+                  <span className="text-ds-text-muted">{c.voyages} voyage{c.voyages !== 1 ? 's' : ''}</span>
+                  <span className="font-medium text-ds-text">${fmt(c.totalSavings)} saved</span>
+                  <span className="text-ds-text-muted text-xs">${fmt(c.avgSavings)}/voyage</span>
+                </div>
+              ))}
+            </div>
+          </Card>
+        ) : (
+          <Card padding="md">
+            <p className="text-sm text-ds-text-muted text-center py-4">
+              No voyage data in the last 90 days. ROI metrics are recorded automatically as matches are closed.
+            </p>
+          </Card>
+        )}
+      </div>
+    </main>
+  );
+}
