-  // Greedy: buy everything at cheapest port
-  const bunkerPlan: BunkerPlanEntry[] = [
-    { port: cheapest.port, volumeMt: Math.round(totalFuelMt) },
-  ];
-
-  const savingsUsd = cheapest.port !== mostExpensive.port
